static const struct tee_cryp_obj_type_props *tee_svc_find_type_props( /* <=== tee_svc_find_type_props */ 
		TEE_ObjectType obj_type)
{
	size_t n;

	for (n = 0; n < ARRAY_SIZE(tee_cryp_obj_props); n++) {
		if (tee_cryp_obj_props[n].obj_type == obj_type)
			return tee_cryp_obj_props + n;
	}

	return NULL;
}

static TEE_Result tee_svc_cryp_get_state(struct tee_ta_session *sess, /* <=== tee_svc_cryp_get_state */ 
					 uint32_t state_id,
					 struct tee_cryp_state **state)
{
	struct tee_cryp_state *s;
	struct user_ta_ctx *utc = to_user_ta_ctx(sess->ctx);

	TAILQ_FOREACH(s, &utc->cryp_states, link) {
		if (state_id == (vaddr_t)s) {
			*state = s;
			return TEE_SUCCESS;
		}
	}
	return TEE_ERROR_BAD_PARAMETERS;
}

TEE_Result __weak crypto_rng_read(void *buf, size_t blen) /* <=== crypto_rng_read */ 
{
	uint8_t *b = buf;
	size_t n;

	if (!b)
		return TEE_ERROR_BAD_PARAMETERS;

	for (n = 0; n < blen; n++)
		b[n] = hw_get_random_byte();

	return TEE_SUCCESS;
}

