static TEE_Result drain_ring_buffer(void) /* <=== drain_ring_buffer */ 
{
	while (true) {
		TEE_Result res;
		uint8_t snum;
		uint8_t pnum;
		uint8_t data[RING_BUF_DATA_SIZE];
		size_t dlen;

		dlen = pop_ring_buffer(&snum, &pnum, data);
		if (!dlen)
			return TEE_SUCCESS;

		res = add_event(snum, pnum, data, dlen);
		if (res)
			return res;
	}
}

static TEE_Result tee_svc_obj_generate_key_dsa( /* <=== tee_svc_obj_generate_key_dsa */ 
	struct tee_obj *o, const struct tee_cryp_obj_type_props *type_props,
	uint32_t key_size)
{
	TEE_Result res;

	res = crypto_acipher_gen_dsa_key(o->attr, key_size);
	if (res != TEE_SUCCESS)
		return res;

	/* Set bits for all known attributes for this object type */
	o->have_attrs = (1 << type_props->num_type_attrs) - 1;

	return TEE_SUCCESS;
}

TEE_Result crypto_bignum_bin2bn(const uint8_t *from, size_t fromsize, /* <=== crypto_bignum_bin2bn */ 
			 struct bignum *to)
{
	if (mbedtls_mpi_read_binary((mbedtls_mpi *)to, (const void *)from,
				    fromsize))
		return TEE_ERROR_BAD_PARAMETERS;
	return TEE_SUCCESS;
}

static uint32_t get_attribute(const struct tee_obj *o, /* <=== get_attribute */ 
			      const struct tee_cryp_obj_type_props *props,
			      uint32_t attr)
{
	int idx = tee_svc_cryp_obj_find_type_attr_idx(attr, props);

	if (idx < 0)
		return 0;
	return o->have_attrs & BIT(idx);
}

static void raw_free(void *ptr, struct bpoolset *poolset) /* <=== raw_free */ 
{
	raw_malloc_validate_pools();

	if (ptr)
		brel(ptr, poolset);
}

void *calloc(size_t nmemb, size_t size) /* <=== calloc */ 
{
	void *p;
	uint32_t exceptions = malloc_lock();

	p = raw_calloc(0, 0, nmemb, size, &malloc_poolset);
	malloc_unlock(exceptions);
	return p;
}

static void *raw_calloc(size_t hdr_size, size_t ftr_size, size_t pl_nmemb, /* <=== raw_calloc */ 
			size_t pl_size, struct bpoolset *poolset)
{
	void *ptr = NULL;
	bufsize s;

	raw_malloc_validate_pools();

	/* Compute total size */
	if (MUL_OVERFLOW(pl_nmemb, pl_size, &s))
		goto out;
	if (ADD_OVERFLOW(s, hdr_size, &s))
		goto out;
	if (ADD_OVERFLOW(s, ftr_size, &s))
		goto out;

	/* BGET doesn't like 0 sized allocations */
	if (!s)
		s++;

	ptr = bgetz(s, poolset);
out:
	raw_malloc_return_hook(ptr, pl_nmemb * pl_size, poolset);

	return ptr;
}

static void *raw_malloc(size_t hdr_size, size_t ftr_size, size_t pl_size, /* <=== raw_malloc */ 
			struct bpoolset *poolset)
{
	void *ptr = NULL;
	bufsize s;

	/*
	 * Make sure that malloc has correct alignment of returned buffers.
	 * The assumption is that uintptr_t will be as wide as the largest
	 * required alignment of any type.
	 */
	COMPILE_TIME_ASSERT(SizeQuant >= sizeof(uintptr_t));

	raw_malloc_validate_pools();

	/* Compute total size */
	if (ADD_OVERFLOW(pl_size, hdr_size, &s))
		goto out;
	if (ADD_OVERFLOW(s, ftr_size, &s))
		goto out;

	/* BGET doesn't like 0 sized allocations */
	if (!s)
		s++;

	ptr = bget(s,  poolset);
out:
	raw_malloc_return_hook(ptr, pl_size, poolset);

	return ptr;
}

